// Some portions generated by Claude
import * as cola from 'webcola';
import {graphNodeSize} from './graph-geometry.ts';
import {SpatialGrid, type Bounds} from './spatial-grid.ts';
import {layoutNodeFixed} from './graph-layout-topology.ts';
import {LAYOUT_SPACING as gap} from './graph-layout-spacing.ts';
import type {Graph, PointerPosition} from './graph-types.ts';
import type {LayoutOptions} from './graph-layout-engine.ts';

type Candidate = PointerPosition & {cost: number};
const EPSILON = 0.01;

/** Small best-first frontier. The spatial index, not all node pairs, is queried. */
class Candidates {
  private heap: Candidate[] = [];
  private seen = new Set<string>();
  private origin: PointerPosition;
  constructor(origin: PointerPosition) {this.origin = origin;}
  push(x: number, y: number) {
    const key = `${Math.round(x * 1000)},${Math.round(y * 1000)}`;
    if (this.seen.has(key)) return;
    this.seen.add(key);
    const value = {x, y, cost: (x - this.origin.x) ** 2 + (y - this.origin.y) ** 2};
    let i = this.heap.length; this.heap.push(value);
    while (i) {const parent = (i - 1) >> 1; if (this.heap[parent].cost <= value.cost) break; this.heap[i] = this.heap[parent]; i = parent;}
    this.heap[i] = value;
  }
  pop() {
    if (!this.heap.length) return undefined;
    const first = this.heap[0], last = this.heap.pop()!;
    if (this.heap.length) {
      let i = 0;
      while (i * 2 + 1 < this.heap.length) {
        let child = i * 2 + 1;
        if (child + 1 < this.heap.length && this.heap[child + 1].cost < this.heap[child].cost) child++;
        if (this.heap[child].cost >= last.cost) break;
        this.heap[i] = this.heap[child]; i = child;
      }
      this.heap[i] = last;
    }
    return first;
  }
}

function bounds(p: PointerPosition, width: number, height: number): Bounds {
  return {minX: p.x - width / 2, maxX: p.x + width / 2, minY: p.y - height / 2, maxY: p.y + height / 2};
}

/** Finite, exact card separation: insert fixed obstacles first, then place each
 * movable rectangle into verified free space. Proximity projection is only a
 * starting proposal; its iteration limit cannot leave movable overlaps behind.
 * The final exterior candidate guarantees termination even for coincident piles.
 * Already clear layouts retain their coordinates bit-for-bit.
 */
export function separateLayoutRectangles(graph: Graph, positions: Map<string, PointerPosition>, options: LayoutOptions = {}) {
  const sizes = graph.nodes.map(node => {
    const size = options.nodeSizes?.get(node.id) ?? graphNodeSize(node);
    return {width: size.width + gap.nodeGapX, height: size.height + gap.nodeGapY};
  });
  const fixed = graph.nodes.map(node => layoutNodeFixed(node, options));
  const points = graph.nodes.map(node => {
    const p = positions.get(node.id) ?? {x: node.x ?? 0, y: node.y ?? 0};
    if (!Number.isFinite(p.x) || !Number.isFinite(p.y)) throw new Error('Non-finite layout position.');
    return {x: p.x, y: p.y};
  });
  const initial = new SpatialGrid(256), found: number[] = [];
  let hasOverlap = false;
  points.forEach((p, i) => {
    if (hasOverlap) return;
    const b = bounds(p, sizes[i].width, sizes[i].height);
    if (initial.search(b.minX + EPSILON, b.minY + EPSILON, b.maxX - EPSILON, b.maxY - EPSILON, found).length) hasOverlap = true;
    initial.insert(b);
  });
  if (!hasOverlap) {
    graph.nodes.forEach((node, i) => positions.set(node.id, points[i]));
    return {fixedOverlaps: 0};
  }
  // VPSC provides a low-displacement proposal for modest unconstrained layouts.
  // Verify it below; projection alone is not a non-overlap guarantee.
  if (!fixed.some(Boolean) && points.length <= 1500 && !options.repairOnly) {
    const rects = points.map((p, i) => new cola.Rectangle(p.x - sizes[i].width / 2, p.x + sizes[i].width / 2,
      p.y - sizes[i].height / 2, p.y + sizes[i].height / 2));
    cola.removeOverlaps(rects);
    rects.forEach((r, i) => {if (Number.isFinite(r.cx()) && Number.isFinite(r.cy())) points[i] = {x: r.cx(), y: r.cy()};});
  }
  const index = new SpatialGrid(256), placed: Bounds[] = [];
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  let fixedOverlaps = 0;
  const collisions = (p: PointerPosition, i: number) => {
    const b = bounds(p, sizes[i].width, sizes[i].height);
    return index.search(b.minX + EPSILON / 2, b.minY + EPSILON / 2, b.maxX - EPSILON / 2, b.maxY - EPSILON / 2, found);
  };
  const insert = (p: PointerPosition, i: number) => {
    const b = bounds(p, sizes[i].width, sizes[i].height);
    index.insert(b); placed.push(b);
    minX = Math.min(minX, b.minX); minY = Math.min(minY, b.minY);
    maxX = Math.max(maxX, b.maxX); maxY = Math.max(maxY, b.maxY);
    positions.set(graph.nodes[i].id, {x: p.x, y: p.y});
  };
  points.forEach((p, i) => {
    if (!fixed[i]) return;
    // A contradictory fixed pile cannot be repaired. Report a lower bound
    // after 1,000 conflicts instead of enumerating O(n²) impossible pairs.
    if (fixedOverlaps < 1000) fixedOverlaps = Math.min(1000, fixedOverlaps + collisions(p, i).length);
    insert(p, i);
  });
  points.forEach((origin, i) => {
    if (fixed[i]) return;
    if (!collisions(origin, i).length) {insert(origin, i); return;}
    const candidates = new Candidates(origin), halfW = sizes[i].width / 2, halfH = sizes[i].height / 2;
    candidates.push(origin.x, origin.y);
    let chosen: PointerPosition | undefined;
    for (let attempt = 0; attempt < 128; attempt++) {
      const candidate = candidates.pop();
      if (!candidate) break;
      const blockers = collisions(candidate, i);
      if (!blockers.length) {chosen = candidate; break;}
      // Expanding the faces of intersecting obstacles gives concrete exits,
      // rather than stepping through empty grid cells or testing every node.
      for (const j of blockers) {
        const b = placed[j];
        candidates.push(b.minX - halfW - EPSILON, candidate.y);
        candidates.push(b.maxX + halfW + EPSILON, candidate.y);
        candidates.push(candidate.x, b.minY - halfH - EPSILON);
        candidates.push(candidate.x, b.maxY + halfH + EPSILON);
      }
    }
    if (!chosen) {
      const exits = [{x: minX - halfW - EPSILON, y: origin.y}, {x: maxX + halfW + EPSILON, y: origin.y},
        {x: origin.x, y: minY - halfH - EPSILON}, {x: origin.x, y: maxY + halfH + EPSILON}];
      chosen = exits.reduce((a, b) => (a.x - origin.x) ** 2 + (a.y - origin.y) ** 2 <= (b.x - origin.x) ** 2 + (b.y - origin.y) ** 2 ? a : b);
    }
    insert(chosen, i);
  });
  return {fixedOverlaps};
}
